-- Bestiary: Volume I: DM-only monster data for the handbook.
-- Run this in the Supabase SQL editor after setup.sql. It's safe to run again: it replaces the data.
-- Only accounts with profiles.is_admin = true can read or change these rows, so players can't see them.

create table if not exists public.bestiary (
  key        text primary key,
  data       jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.bestiary enable row level security;

drop policy if exists "bestiary: DM reads" on public.bestiary;
create policy "bestiary: DM reads" on public.bestiary
  for select to authenticated using (public.is_admin());

drop policy if exists "bestiary: DM edits" on public.bestiary;
create policy "bestiary: DM edits" on public.bestiary
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

revoke all on public.bestiary from anon;

