).","role":"Brute","wants":"Its pond to itself.","tactics":"Bites and holds on, and pulls into its shell when it's hurt.","tell":"its neck stretches out slowly.","exploit":"while it's holding someone, it can't move, so everyone else can walk past. On its back it's helpless (as Giant Beetle's Upturned).","type":"Beast","kind":"creature","order":22},{"id":"pack-raptor","name":"Pack Raptor","kr":4,"section":"Beasts","typeLine":"Beast, pack hunter","tags":["pack hunter"],"description":"A feathered, sickle-clawed runner that hunts in clever groups.","hp":30,"hpNote":null,"defence":1,"minHit":0,"speed":"60 ft","stats":{"str":9,"dex":5,"con":9,"int":14,"wis":8,"cha":16},"combat":{"melee":8,"ranged":null,"dodge":12,"disengage":10,"casting":null},"attacks":[{"name":"Sickle Claw","text":"Sickle Claw: 1d12, +1d2 bleed.","multiattack":false,"recharge":null,"limit":null,"damage":["1d12"],"status":[{"dice":"1d2","n":1,"status":"bleed"}]},{"name":"Bite","text":"Bite: 1d8.","multiattack":false,"recharge":null,"limit":null,"damage":["1d8"],"status":[]}],"traits":[{"name":"Pack Hunter","text":"*Pack Hunter*."},{"name":"Flanking Call","text":"*Flanking Call*: when one raptor attacks, another within 30 ft can move 20 ft for free."}],"harvest":"Sickle claws, feathers.","role":"Skirmisher","wants":"Prey cut off from the herd.","tactics":"Two feint at the front while the rest flank.","tell":"they chirp to each other.","exploit":"kill the one doing the calling and the pack loses its coordination.","type":"Beast","kind":"creature","order":23},{"id":"dire-wolf","name":"Dire Wolf","kr":5,"section":"Beasts","typeLine":"Beast, pack hunter","tags":["pack hunter"],"description":"A wolf the size of a pony, and usually the one leading the pack.","hp":42,"hpNote":null,"defence":1,"minHit":0,"speed":"50 ft","stats":{"str":7,"dex":7,"con":7,"int":15,"wis":8,"cha":14},"combat":{"melee":8,"ranged":null,"dodge":12,"disengage":8,"casting":null},"attacks":[{"name":"Bite","text":"Bite: 2d8, +2d2 prone.","mu