)","stats":{"str":null,"dex":7,"con":null,"int":14,"wis":10,"cha":14},"combat":{"melee":8,"ranged":null,"dodge":13,"disengage":11,"casting":null},"attacks":[{"name":"Chilling Touch","text":"Chilling Touch: 2d8, ignoring Min hit, and the target's max HP drops by 1d6 until a long rest.","multiattack":false,"recharge":null,"limit":null,"damage":["2d8"],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Incorporeal","text":"*Incorporeal*."},{"name":"Shadow Meld","text":"*Shadow Meld*: invisible in darkness."},{"name":"Sunlight","text":"*Sunlight*: 1d4 turns of direct sunlight destroys it."}],"harvest":"Shadow essence.","role":"Lurker","wants":"The warmth it can never have again.","tactics":"Touches someone from the dark and slips back out of sight. It's a coward, unlike the Shadow Fiend.","tell":"the torches dim.","exploit":"bright light, and sunlight above all.","type":"Undead","kind":"creature","order":41},{"id":"ghost","name":"Ghost","kr":8,"section":"Undead","typeLine":"Undead, incorporeal","tags":["incorporeal"],"description":"A cold, flickering echo of someone with unfinished business.","hp":40,"hpNote":null,"defence":4,"minHit":0,"speed":"fly 40 ft (hover)","stats":{"str":null,"dex":7,"con":null,"int":10,"wis":6,"cha":6},"combat":{"melee":7,"ranged":null,"dodge":13,"disengage":9,"casting":6},"attacks":[{"name":"Withering Touch","text":"Withering Touch: 2d8, ignoring Min hit.","multiattack":false,"recharge":null,"limit":null,"damage":["2d8"],"status":[]},{"name":"Horrifying Visage","text":"*Horrifying Visage* (3-turn recharge): everyone who can see it makes a WIS save or is frightened for 1d4 turns.","multiattack":false,"recharge":3,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Incorporeal","text":"*Incorporeal*."},{"name":"Possession","text":"*Possession* (3-turn recharge): the target makes a WIS save. The first fail leaves it dazed (it can only move), and a second fail in a row hands its body to the ghost. The target repeats the save each turn. While it's possessing someone the ghost can't be harmed, and damage goes to the host."},{"name":"Unfinished Business","text":"*Unfinished Business*: destroying it without settling its business only banishes it, and it reforms in 1d4 days."}],"harvest":"Ectoplasm.","role":"Controller","wants":"Its unfinished business settled.","tactics":"Frightens the party, then possesses the strongest one.","tell":"the room goes cold.","exploit":"settle its business. If it's possessing someone, hold them down rather than hitting them.","type":"Undead","kind":"creature","order":42},{"id":"vampire-thrall","name":"Vampire Thrall","kr":8,"section":"Undead","typeLine":"Undead","tags":[],"description":"A lesser vampire bound to a master. It's hungry, fast and fully aware of what it has become.","hp":55,"hpNote":null,"defence":2,"minHit":0,"speed":"35 ft, climb 30 ft","stats":{"str":6,"dex":6,"con":null,"int":12,"wis":11,"cha":10},"combat":{"melee":7,"ranged":null,"dodge":11,"disengage":9,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Claws ×2, 1d8 each. If both hit, the target is grabbed.","multiattack":true,"recharge":null,"limit":null,"damage":["1d8"],"status":[]},{"name":"Bite on a grabbed target","text":"Bite on a grabbed target: 2d8, and the thrall heals the same amount.","multiattack":false,"recharge":null,"limit":null,"damage":["2d8"],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Regeneration","text":"*Regeneration*: it heals 5 HP at the start of each turn unless it took fire or light damage since its last turn."},{"name":"Sunlight","text":"*Sunlight*: in direct sunlight it takes 2d10 burn each turn and has disadvantage on everything."},{"name":"Bound","text":"*Bound*: it always knows where its master is, and the master can see through its eyes."}],"harvest":"Thrall blood (cursed reagent).","role":"Skirmisher","wants":"Blood, and its master's approval.","tactics":"Grabs the weakest, drinks, then runs back to its master.","tell":"its eyes flare red before it lunges.","exploit":"sunlight and fire. It will bargain if its master is threatened.","type":"Undead","kind":"creature","order":43},{"id":"wight","name":"Wight","kr":10,"section":"Undead","typeLine":"Undead","tags":[],"description":"A dead warlord that remembers its rank and raises its own soldiers from the people it kills.","hp":70,"hpNote":null,"defence":3,"minHit":3,"speed":"30 ft","stats":{"str":6,"dex":9,"con":null,"int":10,"wis":8,"cha":7},"combat":{"melee":7,"ranged":7,"dodge":13,"disengage":11,"casting":null},"attacks":[{"name":"Longsword","text":"Longsword: 2d8.","multiattack":false,"recharge":null,"limit":null,"damage":["2d8"],"status":[]},{"name":"Longbow","text":"Longbow: range 150 ft, 1d10.","multiattack":false,"recharge":null,"limit":null,"damage":["1d10"],"status":[]},{"name":"Life Drain","text":"*Life Drain*: 1d10, and the target's max HP drops by the same amount until a long rest.","multiattack":false,"recharge":null,"limit":null,"damage":["1d10"],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Raise Soldier","text":"*Raise Soldier*: a humanoid it kills rises as a zombie under its command at the start of its next turn, up to 6 at once."},{"name":"Sunlight","text":"*Sunlight*: disadvantage on everything in direct sunlight."}],"harvest":"Grave-iron weapon.","role":"Leader","wants":"Soldiers for its dead army.","tactics":"Shoots from range, then drains the wounded and raises the fallen.","tell":"it orders its zombies forward before it advances.","exploit":"sunlight, and burn the bodies so they can't rise.","type":"Undead","kind":"creature","order":44},{"id":"wraith","name":"Wraith","kr":14,"section":"Undead","typeLine":"Undead, incorporeal","tags":["incorporeal"],"description":"A shadow of pure hatred for the living. Lights gutter and dim around it.","hp":80,"hpNote":null,"defence":5,"minHit":0,"speed":"fly 60 ft (hover)","stats":{"str":null,"dex":5,"con":nu