0"],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Headless","text":"*Headless*: it can't be blinded or frightened, and crits deal normal damage."},{"name":"Midnight Hunt","text":"*Midnight Hunt*: between midnight and dawn, damage that would destroy it leaves it on 1 HP instead."}],"harvest":"Its scythe.","role":"Solo","wants":"Its head back, or the one who took it.","tactics":"Rides through the party, throws burning heads, and circles back.","tell":"hoofbeats and laughter.","exploit":"find its real head and the hunt ends. Otherwise, hold out until dawn.","type":"Undead","kind":"creature","order":46},{"id":"mummy","name":"Mummy","kr":18,"section":"Undead","typeLine":"Undead","tags":[],"description":"A preserved noble wrapped in grave-linen, bound to guard its tomb for ever.","hp":140,"hpNote":null,"defence":4,"minHit":5,"speed":"25 ft","stats":{"str":4,"dex":15,"con":null,"int":10,"wis":6,"cha":8},"combat":{"melee":6,"ranged":null,"dodge":16,"disengage":16,"casting":7},"attacks":[{"name":"Rotting Fist","text":"Rotting Fist: 3d10, plus the *Rot* curse: the target can't regain HP for the rest of the combat. Afterwards, its max HP drops by 2d6 each day until a tier 4 cleansing lifts the curse.","multiattack":false,"recharge":null,"limit":null,"damage":["3d10"],"status":[]},{"name":"Dreadful Glare","text":"*Dreadful Glare*: one target within 60 ft makes a WIS save or is frightened, +1d2 stun.","multiattack":false,"recharge":null,"limit":null,"damage":[],"status":[{"dice":"1d2","n":1,"status":"stun"}]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Flammable","text":"*Flammable*: fire deals double damage to it and sets it burning for 2d6 a turn over 3 turns."},{"name":"Tomb-bound","text":"*Tomb-bound*: it fully reforms in a day unless its sealed heart vessel is destroyed."}],"harvest":"Grave-linen, grave goods.","role":"Solo","wants":"Its tomb left undisturbed.","tactics":"Advances slowly, glares, and crushes.","tell":"its wrappings stir as if in a wind.","exploit":"fire. Return what was taken and it goes back to rest.","type":"Undead","kind":"creature","order":47},{"id":"banshee","name":"Banshee","kr":20,"section":"Undead","typeLine":"Undead, incorporeal","tags":["incorporeal"],"description":"A grieving spirit whose cry can stop a heart.","hp":90,"hpNote":null,"defence":6,"minHit":0,"speed":"fly 50 ft (hover)","stats":{"str":null,"dex":4,"con":null,"int":9,"wis":5,"cha":4},"combat":{"melee":6,"ranged":null,"dodge":13,"disengage":10,"casting":4},"attacks":[{"name":"Corrupting Touch","text":"Corrupting Touch: 3d8.","multiattack":false,"recharge":null,"limit":null,"damage":["3d8"],"status":[]},{"name":"Wail","text":"*Wail* (once per combat): every living creature within 60 ft makes a WIS save. On a fail it takes 4d10 and +2d2 stun; on a pass, half damage and no stun.","multiattack":false,"recharge":null,"limit":"once per combat","damage":["4d10"],"status":[{"dice":"2d2","n":2,"status":"stun"}]},{"name":"Mournful Song","text":"*Mournful Song* (2-turn recharge): everyone within 30 ft makes a WIS save or is frightened and can't move closer to it.","multiattack":false,"recharge":2,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Incorporeal","text":"*Incorporeal*."},{"name":"Sense Life","text":"*Sense Life*: it knows where every living creature within 5 miles is."}],"harvest":"A scrap of its veil.","role":"Controller","wants":"Someone to share its grief, or the one it lost.","tactics":"Sings to pin the party in place, then Wails.","tell":"it falls silent and draws a breath the turn before the Wail.","exploit":"anyone who's deafened is immune to the Wail. Speaking the name of the one it mourns makes it hesitate for a turn.","type":"Undead","kind":"creature","order":48},{"id":"revenant","name":"Revenant","kr":24,"section":"Undead","typeLine":"Undead","tags":[],"description":"Someone murdered so cruelly they came back for the killer. It's single-minded and almost impossible to stop.","hp":180,"hpNote":null,"defence":4,"minHit":5,"speed":"35 ft","stats":{"str":3,"dex":8,"con":null,"int":11,"wis":7,"cha":9},"combat":{"melee":6,"ranged":null,"dodge":16,"disengage":16,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Fists or weapon ×2, 2d12 each, doubled against its quarry.","multiattack":true,"recharge":null,"limit":null,"damage":["2d12"],"status":[]},{"name":"Vengeful Glare","text":"*Vengeful Glare*: its quarry makes a WIS save. The first fail leaves it slowed, and a second fail in a row paralyses it for 1 turn.","multiattack":false,"recharge":null,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Regeneration","text":"*Regeneration*: it heals 10 HP a turn unless it took fire or light damage since its last turn."},{"name":"Unfinished Vengeance","text":"*Unfinished Vengeance*: if it's destroyed before its quarry dies, a new body rises within 24 hours, somewhere within a mile of the quarry. It always knows which way its quarry is, and when the quarry dies it crumbles to dust."}],"harvest":"None. The body crumbles.","role":"Solo","wants":"Its killer dead.","tactics":"Ignores everyone except its quarry, unless they get in the way.","tell":"it always walks straight towards the quarry.","exploit":"help it, or hand the quarry over. A revenant can be an ally.","type":"Undead","kind":"creature","order":49},{"id":"plague-lord","name":"Plague Lord","kr":30,"section":"Undead","typeLine":"Undead","tags":[],"description":"A rotting priest of pestilence leading a shuffling host of plague corpses.","hp":260,"hpNote":null,"defence":3,"minHit":5,"speed":"30 ft","stats":{"str":6,"dex":12,"con":null,"int":6,"wis":5,"cha":7},"combat":{"melee":5,"ranged":null,"dodge":12,"disengage":10,"casting":4},"attacks":[{"name":"Censer flail","text":"Censer flail: 3d10, +3d2 disease.","multiattack":false,"recharge":null,"limit":null,"damage":["3d10"],"status":[{"dice":"3d2","n":3,"status":"disease"}]},{"name":"Plague Breath","text":"*Plague Breath* (2-turn recharge): a 30 ft cone, 6d10, +3d2 disease. A strength save halves the damage.","multiattack":false,"recharge":2,"limit":null,"damage":["6d10"],"status":[{"dice":"3d2","n":3,"status":"disease"}]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–5 of the death school."},{"name":"Pestilent Aura","text":"*Pestilent Aura*: living creatures within 20 ft can't heal above half their max HP."},{"name":"Rot Host","text":"*Rot Host*: once a turn, it can make one Plague Corpse within 60 ft Burst."}],"harvest":"Censer (plague reagent), 3d10 gold.","role":"Leader","wants":"To spread the plague.","tactics":"Stays behind its plague corpses and breathes on anyone bunched up.","tell":"the censer smoke thickens before Plague Breath.","exploit":"burn the corpses before they burst. Kill it and they stop moving.","type":"Undead","kind":"creature","order":50},{"id":"fallen-knight","name":"Fallen Knight","kr":36,"section":"Undead","typeLine":"Undead","tags":[],"description":"A champion who broke their oath and was refused death for it.","hp":300,"hpNote":null,"defence":5,"minHit":7,"speed":"30 ft","stats":{"str":3,"dex":10,"con":null,"int":8,"wis":7,"cha":5},"combat":{"melee":5,"ranged":null,"dodge":12,"disengage":10,"casting":6},"attacks":[{"name":"Multiattack","text":"Multiattack: Oathbreaker Blade ×2, 3d12 each, +2d2 madness.","multiattack":true,"recharge":null,"limit":null,"damage":["3d12"],"status":[{"dice":"2d2","n":2,"status":"madness"}]},{"name":"Dark Smite","text":"*Dark Smite* (3-turn recharge): its next hit deals an extra 6d10, and the target can't be healed until the end of its next turn.","multiattack":false,"recharge":3,"limit":null,"damage":["6d10"],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Aura of Despair","text":"*Aura of Despair*: enemies within 20 ft have disadvantage on saves against fear."},{"name":"Command the Dead","text":"*Command the Dead* (as Bone Knight, for any undead of KR 8 or lower)."},{"name":"Oath-cursed","text":"*Oath-cursed*: 1d4 turns after it drops to 0 HP, it rises again with half its HP, unless it was hit with light magic while it was down."}],"harvest":"Blackened plate, the Oathbreaker Blade (cursed).","role":"Solo","wants":"A redemption it no longer believes in.","tactics":"Seeks out and duels the strongest fighter.","tell":"its blade glows black before a Dark Smite.","exploit":"hit it with light magic while it's down. Reminding it of its oath (CHA check) makes it hesitate for a turn.","type":"Undead","kind":"creature","order":51},{"id":"bone-colossus","name":"Bone Colossus","kr":40,"section":"Undead","typeLine":"Undead, mindless","tags":["mindless"],"description":"Thousands of skeletons fused into one forty-foot giant by a necromancer's great working.","hp":350,"hpNote":null,"defence":3,"minHit":6,"speed":"40 ft","stats":{"str":2,"dex":15,"con":null,"int":20,"wis":14,"cha":20},"combat":{"melee":5,"ranged":7,"dodge":17,"disengage":17,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Bone Fists ×2, reach 15 ft, 3d12 each.","multiattack":true,"recharge":null,"limit":null,"damage":["3d12"],"status":[]},{"name":"Hurl Skeletons","text":"*Hurl Skeletons*: range 90 ft. Three Skeletons land around a point, and everyone there takes 2d10.","multiattack":false,"recharge":null,"limit":null,"damage":["2d10"],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Mindless","text":"*Mindless*."},{"name":"Brittle","text":"*Brittle*."},{"name":"Shedding","text":"*Shedding*: for every 50 damage it takes, a Skeleton falls off and keeps fighting."}],"harvest":"A great deal of bone dust.","role":"Brute","wants":"To obey.","tactics":"Wades in and throws skeletons at the back line.","tell":"it reaches into its own ribcage before Hurl Skeletons.","exploit":"bludgeoning, or kill the necromancer behind it.","type":"Undead","kind":"creature","order":52},{"id":"vampire","name":"Vampire","kr":50,"section":"Undead","typeLine":"Undead","tags":[],"description":"A master vampire: old, charming and endlessly patient. Thralls serve it, and whole towns owe it favours.","hp":400,"hpNote":null,"defence":4,"minHit":6,"speed":"40 ft, climb 40 ft","stats":{"str":3,"dex":4,"con":null,"int":5,"wis":5,"cha":2},"combat":{"melee":4,"ranged":null,"dodge":10,"disengage":8,"casting":4},"attacks":[{"name":"Multiattack","text":"Multiattack: Claws ×2, 2d12 each, and a target hit by both is grabbed.","multiattack":true,"recharge":null,"limit":null,"damage":["2d12"],"status":[]},{"name":"Bite on a grabbed target","text":"Bite on a grabbed target: 3d12. The vampire heals that much, and the target's max HP drops by the same until a long rest.","multiattack":false,"recharge":null,"limit":null,"damage":["3d12"],"status":[]},{"name":"Commanding Gaze","text":"*Commanding Gaze*: one target makes a WIS save. The first fail leaves it dazed, and a second fail in a row charms it for 1d4 turns in combat, or an hour outside combat.","multiattack":false,"recharge":null,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Regeneration","text":"*Regeneration*: it heals 20 HP a turn unless it took fire or light damage, or crossed running water, since its last turn."},{"name":"Mist Escape","text":"*Mist Escape*: at 0 HP it turns to mist and returns to its resting place, where it reforms in an hour. To destroy it for good, stake it in its resting place, then behead it or leave it in sunlight."},{"name":"Shapechange","text":"*Shapechange*: into a bat, a wolf or mist."},{"name":"Children of the Night","text":"*Children of the Night* (once per combat): it calls 1d4 Bat Swarms or 1d4 Wolves."},{"name":"Sunlight","text":"*Sunlight*: in direct sunlight it takes 4d10 burn a turn and has disadvantage on everything."},{"name":"Master","text":"*Master*: it commands any Vampire Thralls it has made."}],"harvest":"Master's blood (a powerful cursed reagent), its hoard.","role":"Solo","wants":"Power, comfort and a bloodline.","tactics":"Charms one target, lets its thralls fight, and escapes as mist.","tell":"it smiles before it uses its gaze.","exploit":"running water and sunlight. It can't enter a home uninvited. Find its resting place.","type":"Undead","kind":"creature","order":53},{"id":"lich","name":"Lich","kr":85,"section":"Undead","typeLine":"Undead","tags":[],"description":"A great caster who cheated death by hiding their soul in a vessel. Its plans run for centuries.","hp":650,"hpNote":null,"defence":6,"minHit":8,"speed":"30 ft","stats":{"str":12,"dex":8,"con":null,"int":1,"wis":2,"cha":3},"combat":{"melee":9,"ranged":null,"dodge":13,"disengage":10,"casting":1},"attacks":[{"name":"Paralysing Touch","text":"Paralysing Touch: 3d10, +2d2 paralysis.","multiattack":false,"recharge":null,"limit":null,"damage":["3d10"],"status":[{"dice":"2d2","n":2,"status":"paralysis"}]},{"name":"Death Bolt","text":"*Death Bolt*: range 120 ft, 6d10, +2d2 wither.","multiattack":false,"recharge":null,"limit":null,"damage":["6d10"],"status":[{"dice":"2d2","n":2,"status":"wither"}]},{"name":"Raise Horde","text":"*Raise Horde* (once per combat): 2d6 Zombies or Skeletons rise from the ground around it.","multiattack":false,"recharge":null,"limit":"once per combat","damage":[],"status":[]}],"traits":[{"name":"Undead","text":"*Undead*."},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–7 in any two schools, usually death and dark."},{"name":"Lich's Tempo","text":"*Lich's Tempo*: it acts twice a round."},{"name":"Magic Resistant","text":"*Magic Resistant* (as Stone Golem)."},{"name":"Soul Vessel","text":"*Soul Vessel*: when it's destroyed, it reforms next to its soul vessel in 1d10 days. It only stays dead if the vessel is destroyed first."}],"harvest":"Spellbook (tier 5–7 spells), its soul vessel if it's found.","role":"Solo","wants":"Knowledge, and all the time in the world.","tactics":"Raises a horde, stays behind it, and bolts the most dangerous target.","tell":"dark energy gathers around its hands a turn before Raise Horde.","exploit":"the soul vessel. Its magic resistance doesn't protect it from weapons.","type":"Undead","kind":"creature","order":54},{"id":"elder-vampire","name":"Elder Vampire","kr":90,"section":"Undead","typeLine":"Undead","tags":[],"description":"A vampire old enough to have founded bloodlines. It rules from a fortress, with a court of thralls.","hp":750,"hpNote":null,"defence":6,"minHit":9,"speed":"50 ft, climb 50 ft, fly 60 ft","stats":{"str":2,"dex":3,"con":null,"int":2,"wis":3,"cha":1},"combat":{"melee":4,"ranged":null,"dodge":10,"disengage":8,"casting":2},"attacks":[{"name":"Multiattack","text":"Multiattack: Claws ×2, 3d12 each, and a target hit by both is grabbed.","multiattack":true,"recharge":null,"limit":null,"damage":["3d12"],"status":[]},{"name":"Bite on a grabbed target","text":"Bite on a grabbed target: 4d12. It heals that much, and the target's max HP drops by the same until a long rest.","multiattack":false,"recharge":null,"limit":null,"damage":["4d12"],"status":[]},{"name":"Commanding Gaze","text":"*Commanding Gaze* (as Vampire, but the save is made at disadvantage).","multiattack":false,"recharge":null,"limit":"as Vampire, but the save is made at disadvantage","damage":[],"status":[]},{"name":"Blood Tide","text":"*Blood Tide* (3-turn recharge): every bleeding creature within 60 ft makes a STR save or takes 8d10 as the blood is pulled out of it. The elder heals half the total.","multiattack":false,"recharge":3,"limit":null,"damage":["8d10"],"status":[]}],"traits":[{"name":null,"text":"Everything the Vampire has, plus:"},{"name":"Elder's Tempo","text":"*Elder's Tempo*: it acts twice a round."},{"name":"Regeneration","text":"*Regeneration*: 40 HP a turn."},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–7 of the dark school."},{"name":"Old Blood","text":"*Old Blood*: sunlight still hurts it, but can't destroy it."}],"harvest":"Elder's blood (a legendary cursed reagent), its fortress's treasury.","role":"Solo","wants":"An empire of the night.","tactics":"Courtly at first. Then it gets the party bleeding and uses Blood Tide.","tell":"every candle in the room gutters red before Blood Tide.","exploit":"everything that works on a Vampire, plus its old rivals.","type":"Undead","kind":"creature","order":55},{"id":"dracolich","name":"Dracolich","kr":180,"section":"Undead","typeLine":"Undead, dragon","tags":["dragon"],"description":"An Elder Dragon that refused to die. Now it's bones, rot and hatred, bound to a soul vessel.","hp":1500,"hpNote":null,"defence":6,"minHit":10,"speed":"40 ft, fly 100 ft","stats":{"str":2,"dex":7,"con":null,"int":3,"wis":4,"cha":3},"combat":{"melee":3,"ranged":4,"dodge":13,"disengage":11,"casting":2},"attacks":[{"name":"Bite","text":"Bite: 4d20, +3d2 wither.","multiattack":false,"recharge":null,"limit":null,"damage":["4d20"],"status":[{"dice":"3d2","n":3,"status":"wither"}]},{"name":"Multiattack","text":"Multiattack: Claws ×2, 3d20 each.","multiattack":true,"recharge":null,"limit":null,"damage":["3d20"],"status":[]},{"name":"Tail","text":"Tail: reach 25 ft, 3d12.","multiattack":false,"recharge":null,"limit":null,"damage":["3d12"],"status":[]},{"name":"Death Breath","text":"*Death Breath* (2-turn recharge): a 120 ft cone, 15d10, +6d2 wither. A Dodge roll halves the damage.","multiattack":false,"recharge":2,"limit":null,"damage":["15d10"],"status":[{"dice":"6d2","n":6,"status":"wither"}]}],"traits":[{"name":"Undead","text":"*Undead*. Everything the Elder Dragon has except Human Guise. It keeps its living flavour's immunity and gains the Death flavour on top."},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–7 of the death school."},{"name":"Soul Vessel","text":"*Soul Vessel* (as Lich)."}],"harvest":"Dracolich bone (a legendary death-school core).","role":"Solo","wants":"Dominion, and revenge on the living.","tactics":"Breathes first, then crushes the casters.","tell":