der","tags":["leader"],"description":"The one the bandits are more afraid of than they are of you.","hp":40,"hpNote":null,"defence":2,"minHit":2,"speed":"30 ft","stats":{"str":8,"dex":7,"con":9,"int":10,"wis":10,"cha":7},"combat":{"melee":8,"ranged":8,"dodge":12,"disengage":10,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Scimitar 1d10 and Dagger 1d6.","multiattack":true,"recharge":null,"limit":null,"damage":["1d10","1d6"],"status":[]}],"traits":[{"name":"Rally","text":"*Rally* (once per combat): every bandit within 30 ft heals 1d6 and automatically passes its next morale check."},{"name":"Parry","text":"*Parry*: once a turn, it can make a Dodge roll to halve a melee hit."}],"harvest":"3d10 silver and 1d4 gold, a decent blade.","role":"Leader","wants":"A profitable job.","tactics":"Rallies the bandits and duels the party's leader.","tell":"barked orders.","exploit":"kill or capture it and the rest surrender. It can also be bribed.","type":"Humanoid","kind":"creature","order":66},{"id":"cult-priest","name":"Cult Priest","kr":6,"section":"Humanoids","typeLine":"Humanoid, caster","tags":["caster"],"description":"The voice of the cult. Pick light or dark for it: dark for a corrupted cult, light for zealots.","hp":34,"hpNote":null,"defence":1,"minHit":0,"speed":"30 ft","stats":{"str":12,"dex":11,"con":11,"int":9,"wis":6,"cha":7},"combat":{"melee":10,"ranged":null,"dodge":15,"disengage":13,"casting":6},"attacks":[{"name":"Dark","text":"*Dark*: Corrupting Bolt, range 60 ft, 2d10, +1d2 madness. Siphon, range 30 ft, 1d10, healing itself the same amount.","multiattack":false,"recharge":null,"limit":null,"damage":["2d10","1d10"],"status":[{"dice":"1d2","n":1,"status":"madness"}]},{"name":"Light","text":"*Light*: Searing Ray, range 60 ft, 2d10, +1d2 blinded. Mend, healing an ally 2d8.","multiattack":false,"recharge":null,"limit":null,"damage":["2d10","2d8"],"status":[{"dice":"1d2","n":1,"status":"blinded"}]}],"traits":[{"name":"Tiers 1–3","text":"*Tiers 