generation*: 15 HP a turn."},{"name":"Keen Nose","text":"*Keen Nose*."}],"harvest":"Pelt.","role":"Solo","wants":"Its forest protected.","tactics":"Defends, but never chases.","tell":"it rears up roaring.","exploit":"it's usually on the side of good, so talk to it.","type":"Monstrous","kind":"creature","order":93},{"id":"frost-troll","name":"Frost Troll","kr":24,"section":"Monstrous","typeLine":"Monstrous, giant-kin","tags":["giant-kin"],"description":"A white, ice-crusted troll that fire barely bothers.","hp":200,"hpNote":null,"defence":3,"minHit":5,"speed":"30 ft","stats":{"str":3,"dex":12,"con":3,"int":16,"wis":12,"cha":17},"combat":{"melee":6,"ranged":null,"dodge":16,"disengage":15,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Claws ×2, 2d10 each, +1d2 freeze, and Bite 2d8.","multiattack":true,"recharge":null,"limit":null,"damage":["2d10","2d8"],"status":[{"dice":"1d2","n":1,"status":"freeze"}]}],"traits":[{"name":null,"text":"Immune to cold."},{"name":"Regeneration","text":"*Regeneration*: 15 HP a turn. It only stops if it took acid damage, or fire damage twice, since its last turn."}],"harvest":"Frost troll blood.","role":"Solo","wants":"Food.","tactics":"Fights like a Troll, with frost spreading underfoot.","tell":"frost creeps across the ground ahead of it.","exploit":"acid, or fire twice in a turn.","type":"Monstrous","kind":"creature","order":94},{"id":"hill-giant","name":"Hill Giant","kr":28,"section":"Monstrous","typeLine":"Monstrous, giant","tags":["giant"],"description":"Twenty feet tall, slow-witted, and swinging an uprooted tree.","hp":220,"hpNote":null,"defence":2,"minHit":6,"speed":"40 ft","stats":{"str":2,"dex":15,"con":3,"int":16,"wis":14,"cha":15},"combat":{"melee":5,"ranged":7,"dodge":17,"disengage":17,"casting":null},"attacks":[{"name":"Tree-trunk club","text":"Tree-trunk club: reach 15 ft, 3d20.","multiattack":false,"recharge":null,"limit":null,"damage":["3d20"],"status":[]},{"name":"Boulder","text":"Boulder: range 120 ft, 3d12, +1d2 prone.","multiattack":false,"recharge":null,"limit":null,"damage":["3d12"],"status":[{"dice":"1d2","n":1,"status":"prone"}]},{"name":"Stomp","text":"*Stomp*: one smaller creature next to it takes 2d12, +2d2 prone.","multiattack":false,"recharge":null,"limit":null,"damage":["2d12"],"status":[{"dice":"2d2","n":2,"status":"prone"}]}],"traits":[{"name":"Dim","text":"*Dim* (as Ogre)."},{"name":"Huge","text":"*Huge*: smaller creatures can climb it (STR check) and have advantage on attacks while they're on it."}],"harvest":"A sack holding 4d20 silver and 1d10 gold, hide.","role":"Solo","wants":"Food, and shiny things.","tactics":"Throws boulders as you approach, then smashes.","tell":"it picks up a boulder.","exploit":"trick it, or climb it.","type":"Monstrous","kind":"creature","order":95},{"id":"hydra","name":"Hydra","kr":32,"section":"Monstrous","typeLine":"Monstrous, reptile","tags":["reptile"],"description":"A swamp serpent with five heads, and more every time you cut one off.","hp":250,"hpNote":null,"defence":2,"minHit":4,"speed":"30 ft, swim 30 ft","stats":{"str":3,"dex":12,"con":3,"int":18,"wis":10,"cha":17},"combat":{"melee":5,"ranged":null,"dodge":16,"disengage":16,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Bite, one per head, 1d12 each.","multiattack":true,"recharge":null,"limit":null,"damage":["1d12"],"status":[]}],"traits":[{"name":"Many Heads","text":"*Many Heads*: it starts with 5 heads. Every 50 damage it takes severs one. At the end of its turn, each severed stump grows two new heads unless it took fire or acid damage that turn. It can have up to 12 heads, and it dies when every head is gone."},{"name":"Wakeful","text":"*Wakeful*: one head is always awake, so it can't be surprised."}],"harvest":"Hydra blood (regeneration potions), teeth.","role":"Solo","wants":"Food, and its swamp.","tactics":"Bites everyone in reach, and gets nastier as heads regrow.","tell":"the heads weave apart to pick targets.","exploit":"cut, then burn. Without fire, cutting only makes it worse.","type":"Monstrous","kind":"creature","order":96},{"id":"stone-giant","name":"Stone Giant","kr":40,"section":"Monstrous","typeLine":"Monstrous, giant","tags":["giant"],"description":"Grey, solemn and deep in the mountains. It throws boulders with a sculptor's precision.","hp":320,"hpNote":null,"defence":4,"minHit":7,"speed":"40 ft","stats":{"str":2,"dex":9,"con":2,"int":12,"wis":8,"cha":12},"combat":{"melee":5,"ranged":4,"dodge":14,"disengage":14,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Greatclub ×2, 3d12 each.","multiattack":true,"recharge":null,"limit":null,"damage":["3d12"],"status":[]},{"name":"Boulder","text":"Boulder: range 240 ft, 4d12, +2d2 prone.","multiattack":false,"recharge":null,"limit":null,"damage":["4d12"],"status":[{"dice":"2d2","n":2,"status":"prone"}]}],"traits":[{"name":"Stone Camouflage","text":"*Stone Camouflage*: advantage on Stealth among rocks."},{"name":"Rock Catch","text":"*Rock Catch*: as a reaction, it catches a thrown rock or similar object and can throw it straight back."}],"harvest":"Carved stone tokens, 2d10 gold.","role":"Artillery","wants":"Solitude, and its art.","tactics":"Throws boulders from range and only closes in when it has to.","tell":"it hefts a boulder onto its shoulder.","exploit":"stone giants are peaceful at heart. A gift of carved stone opens talks.","type":"Monstrous","kind":"creature","order":97},{"id":"sandworm","name":"Sandworm","kr":40,"section":"Monstrous","typeLine":"Monstrous, burrower","tags":["burrower"],"description":"A desert worm a hundred feet long that you only see the moment it comes up underneath you.","hp":400,"hpNote":null,"defence":3,"minHit":7,"speed":"30 ft, burrow 50 ft","stats":{"str":1,"dex":16,"con":1,"int":20,"wis":12,"cha":20},"combat":{"melee":5,"ranged":null,"dodge":17,"disengage":15,"casting":null},"attacks":[{"name":"Bite","text":"Bite: 4d12, and a target smaller than it is swallowed.","multiattack":false,"recharge":null,"limit":null,"damage":["4d12"],"status":[]},{"name":"Erupt","text":"*Erupt*: it bursts up under a 30 ft area, and everyone there makes a Dodge roll or takes 3d10 and is knocked prone. One creature that fails is also bitten.","multiattack":false,"recharge":null,"limit":null,"damage":["3d10"],"status":[]}],"traits":[{"name":"Swallow","text":"*Swallow*: a swallowed creature is blinded and takes 3d10 acid at the start of each of its turns. Dealing 40 damage from inside makes the worm spit it out."},{"name":"Tremorsense","text":"*Tremorsense*: it senses anything moving on sand within 300 ft. A creature standing completely still has advantage on Stealth against it."},{"name":"Submerge","text":"*Submerge*: after attacking, it can burrow down and can't be targeted until it surfaces again."}],"harvest":"Teeth (weapon material), hide plates.","role":"Solo","wants":"Anything moving on the sand.","tactics":"Erupts, swallows and submerges, then does it again.","tell":"the sand trembles and the dunes ripple.","exploit":"stand still, or get onto rock where it can't follow.","type":"Monstrous","kind":"creature","order":98},{"id":"sky-whale","name":"Sky Whale","kr":40,"section":"Monstrous","typeLine":"Monstrous, flier","tags":["flier"],"description":"A whale that swims through the clouds. It's gentle until something threatens its calf.","hp":400,"hpNote":null,"defence":2,"minHit":7,"speed":"fly 60 ft","stats":{"str":1,"dex":17,"con":1,"int":14,"wis":6,"cha":10},"combat":{"melee":5,"ranged":null,"dodge":19,"disengage":17,"casting":null},"attacks":[{"name":"Tail Slam","text":"Tail Slam: 4d12, +2d2 prone (a flier is knocked out of the sky).","multiattack":false,"recharge":null,"limit":null,"damage":["4d12"],"status":[{"dice":"2d2","n":2,"status":"prone"}]},{"name":"Bite","text":"Bite: 3d12, and a smaller target is swallowed (as Sandworm, 2d10 acid a turn).","multiattack":false,"recharge":null,"limit":null,"damage":["3d12","2d10"],"status":[]}],"traits":[{"name":"Living Island","text":"*Living Island*: small creatures can stand on its back."},{"name":"Whale Song","text":"*Whale Song*: its call carries 50 miles, and other sky whales come."},{"name":"Gentle","text":"*Gentle*: it's benevolent unless it's provoked."}],"harvest":"Ambergris (very valuable), baleen. Hunting them is frowned on.","role":"Set piece","wants":"Peace, and its calf safe.","tactics":"Flees unless its calf is threatened, and then it's terrifying. A good encounter is about saving the calf, riding the whale, or stopping poachers.","tell":"its song drops deeper.","exploit":"protect its calf and it will carry you anywhere.","type":"Monstrous","kind":"creature","order":99},{"id":"frost-giant","name":"Frost Giant","kr":45,"section":"Monstrous","typeLine":"Monstrous, giant","tags":["giant"],"description":"Raiders out of the ice, with axes, furs and wolves at heel.","hp":360,"hpNote":null,"defence":4,"minHit":7,"speed":"40 ft","stats":{"str":2,"dex":11,"con":2,"int":14,"wis":11,"cha":12},"combat":{"melee":5,"ranged":6,"dodge":14,"disengage":13,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Greataxe ×2, 3d12 each, +1d2 freeze.","multiattack":true,"recharge":null,"limit":null,"damage":["3d12"],"status":[{"dice":"1d2","n":1,"status":"freeze"}]},{"name":"Ice chunk","text":"Ice chunk: range 120 ft, 4d10.","multiattack":false,"recharge":null,"limit":null,"damage":["4d10"],"status":[]}],"traits":[{"name":null,"text":"Immune to cold, and weak to fire."},{"name":"Winter-born","text":"*Winter-born*: ice and snow don't slow it. It usually travels with 1d4 Dire Wolves."}],"harvest":"Furs, greataxe, 4d10 gold.","role":"Soldier","wants":"Plunder and glory.","tactics":"Raids with wolves and duels whoever looks strongest.","tell":"a war horn blast.","exploit":"fire, and they respect a challenge to single combat.","type":"Monstrous","kind":"creature","order":100},{"id":"roc","name":"Roc","kr":50,"section":"Monstrous","typeLine":"Monstrous, flier","tags":["flier"],"description":"A bird so vast it carries off whales and casts towns into shadow.","hp":420,"hpNote":null,"defence":3,"minHit":7,"speed":"20 ft, fly 120 ft","stats":{"str":1,"dex":8,"con":2,"int":16,"wis":5,"cha":14},"combat":{"melee":4,"ranged":null,"dodge":10,"disengage":8,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Beak 4d12 and Talons 4d10, and a target up to Huge size is grabbed.","multiattack":true,"recharge":null,"limit":null,"damage":["4d12","4d10"],"status":[]},{"name":"Carry and Drop","text":"*Carry and Drop* (as Giant Eagle, but it climbs 100 ft).","multiattack":false,"recharge":null,"limit":"as Giant Eagle, but it climbs 100 ft","damage":[],"status":[]}],"traits":[{"name":"Keen Sight","text":"*Keen Sight*."},{"name":"Gale Wings","text":"*Gale Wings*: when it takes off, everything within 60 ft below it makes a STR save or is knocked prone."}],"harvest":"Feathers the size of sails, an egg.","role":"Solo","wants":"Big prey for its chicks.","tactics":"Grabs a target and carries it away.","tell":"a vast shadow passes over the land.","exploit":"it won't follow into narrow canyons. Threaten its nest and it comes to you.","type":"Monstrous","kind":"creature","order":101},{"id":"fire-giant","name":"Fire Giant","kr":55,"section":"Monstrous","typeLine":"Monstrous, giant","tags":["giant"],"description":"Forge-masters from the volcanic deeps, who fight as a disciplined army.","hp":450,"hpNote":null,"defence":5,"minHit":8,"speed":"30 ft","stats":{"str":1,"dex":12,"con":2,"int":10,"wis":9,"cha":10},"combat":{"melee":4,"ranged":6,"dodge":14,"disengage":13,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Greatsword ×2, 4d12 each, +2d2 burn.","multiattack":true,"recharge":null,"limit":null,"damage":["4d12"],"status":[{"dice":"2d2","n":2,"status":"burn"}]},{"name":"Molten rock","text":"Molten rock: range 120 ft, 4d12, and it sets a 10 ft area burning.","multiattack":false,"recharge":null,"limit":null,"damage":["4d12"],"status