ack","text":"Multiattack: Thorned Sceptre ×2, 4d12 each, +3d2 charm.","multiattack":true,"recharge":null,"limit":null,"damage":["4d12"],"status":[{"dice":"3d2","n":3,"status":"charm"}]},{"name":"Court's Command","text":"*Court's Command* (2-turn recharge): everyone within 120 ft makes a WIS save. The first fail leaves them dazed, and a second fail in a row charms them for 1d4 turns, fighting for the monarch.","multiattack":false,"recharge":2,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Fey","text":"*Fey*."},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–9 of the mind and life schools."},{"name":"Monarch's Tempo","text":"*Monarch's Tempo*: it acts three times a round."},{"name":"Step Through","text":"*Step Through* (as Fey Knight, with no range limit inside its realm)."},{"name":"Royal Word","text":"*Royal Word*: any promise made to it, or by it, binds both sides."}],"harvest":"None, but a monarch's favour is worth more than any treasure.","role":"Solo","wants":"Amusement, and the glory of its court.","tactics":"Turns the party against each other.","tell":"it lifts its sceptre before Court's Command.","exploit":"cold iron, and holding it to its promises.","type":"Fey","kind":"creature","order":146},{"id":"spawnling","name":"Spawnling","kr":2,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"A dog-sized, many-eyed thing that leaks through wherever reality is thin.","hp":18,"hpNote":null,"defence":1,"minHit":0,"speed":"30 ft, climb 30 ft","stats":{"str":12,"dex":8,"con":10,"int":15,"wis":12,"cha":18},"combat":{"melee":9,"ranged":null,"dodge":12,"disengage":10,"casting":null},"attacks":[{"name":"Tendril Bite","text":"Tendril Bite: 1d10, +1d2 madness.","multiattack":false,"recharge":null,"limit":null,"damage":["1d10"],"status":[{"dice":"1d2","n":1,"status":"madness"}]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Breeding","text":"*Breeding*: if it spends a turn eating a corpse, a second Spawnling appears."}],"harvest":"Ichor (an unstable reagent).","role":"Skirmisher","wants":"To breed.","tactics":"Goes for corpses first, then for whoever is closest.","tell":"wet clicking in the dark.","exploit":"burn the corpses before it reaches them.","type":"Aberration","kind":"creature","order":147},{"id":"mind-leech","name":"Mind Leech","kr":8,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"A rat-sized slug that latches onto the skull and feeds on thoughts.","hp":30,"hpNote":null,"defence":1,"minHit":0,"speed":"20 ft, climb 20 ft","stats":{"str":15,"dex":8,"con":10,"int":6,"wis":7,"cha":16},"combat":{"melee":7,"ranged":null,"dodge":10,"disengage":9,"casting":6},"attacks":[{"name":"Latch","text":"Latch: 1d6, and it attaches. While it's attached, the host takes 1d10 and +1d2 madness each turn. The host also makes a WIS save each turn: the first fail leaves it dazed, and a second fail in a row hands control of the host to the leech.","multiattack":false,"recharge":null,"limit":null,"damage":["1d6","1d10"],"status":[{"dice":"1d2","n":1,"status":"madness"}]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Telepathic","text":"*Telepathic*."},{"name":"Hard to Remove","text":"*Hard to Remove*: pulling it off takes a STR check, and half of any damage dealt to it goes to the host."}],"harvest":"Leech jelly (a mind reagent).","role":"Lurker","wants":"A host.","tactics":"Latches onto a caster and steers them against their friends.","tell":"an itch at the base of the skull.","exploit":"hot iron makes it let go.","type":"Aberration","kind":"creature","order":148},{"id":"cave-lurker","name":"Cave Lurker","kr":10,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"A rubbery thing that clings to cave ceilings and drops tentacles on anyone passing below.","hp":85,"hpNote":null,"defence":2,"minHit":2,"speed":"15 ft, climb 30 ft","stats":{"str":5,"dex":10,"con":6,"int":15,"wis":9,"cha":18},"combat":{"melee":7,"ranged":null,"dodge":12,"disengage":11,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Tentacles ×2, reach 15 ft, 1d10 each, and the target is grabbed and lifted off the ground.","multiattack":true,"recharge":null,"limit":null,"damage":["1d10"],"status":[]},{"name":"Beak on a grabbed target","text":"Beak on a grabbed target: 2d12.","multiattack":false,"recharge":null,"limit":null,"damage":["2d12"],"status":[]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"False Appearance","text":"*False Appearance*: it looks like a stalactite."},{"name":"Wall-crawler","text":"*Wall-crawler*."}],"harvest":"None.","role":"Lurker","wants":"Food.","tactics":"Drops its tentacles, lifts someone up, and bites.","tell":"dripping from a stalactite that shouldn't be wet.","exploit":"light. It hates being seen.","type":"Aberration","kind":"creature","order":149},{"id":"skin-thief","name":"Skin Thief","kr":15,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"A shapechanger that kills people and wears their faces, lives and friendships.","hp":120,"hpNote":null,"defence":2,"minHit":0,"speed":"30 ft","stats":{"str":8,"dex":6,"con":7,"int":5,"wis":5,"cha":3},"combat":{"melee":6,"ranged":null,"dodge":11,"disengage":9,"casting":6},"attacks":[{"name":"Multiattack","text":"Multiattack: Slam ×2, 2d10 each.","multiattack":true,"recharge":null,"limit":null,"damage":["2d10"],"status":[]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Perfect Mimic","text":"*Perfect Mimic*: it takes the exact form of anyone it has killed, memories included, and only truesight reveals it."},{"name":"Read Thoughts","text":"*Read Thoughts*: it knows the surface thoughts of anyone within 60 ft."}],"harvest":"None.","role":"Skirmisher","wants":"To live someone else's life.","tactics":"Avoids fighting, and frames others instead.","tell":"small inconsistencies in how its victim behaves.","exploit":"its memories stop when its victim died, so ask about anything that happened since.","type":"Aberration","kind":"creature","order":150},{"id":"gloomeye","name":"Gloomeye","kr":24,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"A floating eye five feet across, trailing grasping tendrils. Looking into it is a mistake.","hp":200,"hpNote":null,"defence":4,"minHit":4,"speed":"fly 20 ft (hover)","stats":{"str":null,"dex":9,"con":5,"int":3,"wis":3,"cha":10},"combat":{"melee":6,"ranged":null,"dodge":13,"disengage":11,"casting":3},"attacks":[{"name":"Multiattack","text":"Multiattack: Tendrils ×3, 1d10 each, and the target is grabbed.","multiattack":true,"recharge":null,"limit":null,"damage":["1d10"],"status":[]},{"name":"Gaze of the Void","text":"*Gaze of the Void*: one target within 60 ft makes a WIS save or takes +3d2 madness and loses its next turn.","multiattack":false,"recharge":null,"limit":null,"damage":[],"status":[{"dice":"3d2","n":3,"status":"madness"}]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Unblinking","text":"*Unblinking*: it can't be surprised, and it sees invisible creatures."}],"harvest":"The eye (a scrying focus).","role":"Solo","wants":"To watch, and to be watched.","tactics":"Grabs with its tendrils, then gazes at whoever is held.","tell":"the eye dilates.","exploit":"blindfolds, and it can't see behind itself.","type":"Aberration","kind":"creature","order":151},{"id":"whispering-prophet","name":"Whispering Prophet","kr":30,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"Once a person, now an empty vessel that something from outside speaks through. Cults gather around it.","hp":250,"hpNote":null,"defence":3,"minHit":3,"speed":"30 ft, fly 30 ft (levitating)","stats":{"str":12,"dex":8,"con":6,"int":2,"wis":3,"cha":2},"combat":{"melee":9,"ranged":null,"dodge":14,"disengage":11,"casting":2},"attacks":[{"name":"Mind Spike","text":"Mind Spike: range 120 ft, 4d10, +2d2 madness.","multiattack":false,"recharge":null,"limit":null,"damage":["4d10"],"status":[{"dice":"2d2","n":2,"status":"madness"}]},{"name":"Revelation","text":"*Revelation* (3-turn recharge): everyone within 60 ft makes a WIS save or takes 6d10 and is confused for 1d4 turns.","multiattack":false,"recharge":3,"limit":null,"damage":["6d10"],"status":[]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–6 of the mind school."},{"name":"Prophet's Tempo","text":"*Prophet's Tempo*: it acts twice a round."},{"name":"Flock","text":"*Flock*: cultists within 60 ft never break, and as a reaction it can swap places with one."}],"harvest":"Its prophecies, which are true and terrible.","role":"Solo","wants":"Its message spread.","tactics":"Stays behind its flock and spikes minds from range.","tell":"the whispering grows loud before Revelation.","exploit":"silence it, or expose it as a fraud to its flock.","type":"Aberration","kind":"creature","order":152},{"id":"tunnel-horror","name":"Tunnel Horror","kr":38,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"A many-jointed, chitinous burrower that chews through solid rock.","hp":320,"hpNote":null,"defence":4,"minHit":6,"speed":"30 ft, burrow 20 ft (through rock)","stats":{"str":2,"dex":10,"con":3,"int":14,"wis":10,"cha":18},"combat":{"melee":5,"ranged":null,"dodge":15,"disengage":15,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Hooked limbs ×2, 2d10 each, +2d2 bleed, and Mandibles 3d12.","multiattack":true,"recharge":null,"limit":null,"damage":["2d10","3d12"],"status":[{"dice":"2d2","n":2,"status":"bleed"}]},{"name":"Stone Shriek","text":"*Stone Shriek* (3-turn recharge): everyone in the tunnels within 60 ft makes a strength save or is stunned for 1 turn. Then roll 1d2: on a 2, part of the ceiling collapses for 4d10.","multiattack":false,"recharge":3,"limit":null,"damage":["1d2"],"status":[]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Tremorsense","text":"*Tremorsense*: 120 ft."}],"harvest":"Carapace, hook limbs.","role":"Brute","wants":"To dig.","tactics":"Bursts out of a wall and shrieks to bring the ceiling down.","tell":"a rumble in the stone.","exploit":"fight it in the open, away from tunnels.","type":"Aberration","kind":"creature","order":153},{"id":"the-many-mouthed","name":"The Many-Mouthed","kr":60,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"A heaving mound of flesh, mouths and eyes that never stops whispering.","hp":550,"hpNote":null,"defence":3,"minHit":8,"speed":"20 ft, climb 20 ft","stats":{"str":2,"dex":16,"con":1,"int":6,"wis":3,"cha":16},"combat":{"melee":5,"ranged":null,"dodge":17,"disengage":17,"casting":4},"attacks":[{"name":"Multiattack","text":"Multiattack: Bites, one against each creature within 10 ft (up to 6), 2d8 each, +1d2 madness.","multiattack":true,"recharge":null,"limit":null,"damage":["2d8"],"status":[{"dice":"1d2","n":1,"status":"madness"}]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Gibbering","text":"*Gibbering*: everyone within 60 ft makes a WIS save at the start of their turn. On a fail, roll 1d4: 1, attack the nearest creature; 2, move randomly; 3, do nothing; 4, act normally."},{"name":"Absorb","text":"*Absorb*: a creature it kills becomes part of it, and it heals 50 HP."}],"harvest":"Nothing worth having.","role":"Solo","wants":"To absorb everything.","tactics":"Rolls into a crowd and bites everyone at once.","tell":"the whispers suddenly sync into one voice.","exploit":"ranged attacks and fire. Never let it reach a group.","type":"Aberration","kind":"creature","order":154},{"id":"star-maw","name":"Star Maw","kr":90,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"A floating mouth the size of a hill that fell from between the stars. It eats light and sound.","hp":900,"hpNote":null,"defence":4,"minHit":9,"speed":"fly 40 ft","stats":{"str":1,"dex":15,"con":1,"int":6,"wis":4,"cha":16},"combat":{"melee":4,"ranged":null,"dodge":15,"disengage":13,"casting":3},"attacks":[{"name":"Bite","text":"Bite: 4d20, and a smaller target is swallowed (as Sandworm).","multiattack":false,"recharge":null,"limit":null,"damage":["4d20"],"status":[]},{"name":"Inhale","text":"*Inhale* (2-turn recharge): everything within 120 ft is pulled 30 ft towards it, and a STR save resists.","multiattack":false,"recharge":2,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Maw's Tempo","text":"*Maw's Tempo*: it acts twice a round."},{"name":"Silence and Dark","text":"*Silence and Dark*: within 60 ft of it there's no light and no sound, so no spell that needs speaking can be cast."}],"harvest":"A fragment of star-stuff.","role":"Solo","wants":"Light to eat.","tactics":"Inhales to pull targets in, then swallows them.","tell":"the stars around it dim.","exploit":"a tier 5+ light spell makes it spit out whatever it has swallowed.","type":"Aberration","kind":"creature","order":155},{"id":"the-dreaming-thing","name":"The Dreaming Thing","kr":200,"section":"Aberrations","typeLine":"Aberration","tags":[],"description":"Something vast asleep beneath the sea or the earth. Its dreams leak out as madness, and waking it ends cities.","hp":2200,"hpNote":null,"defence":6,"minHit":12,"speed":"30 ft, swim 60 ft","stats":{"str":1,"dex":15,"con":1,"int":1,"wis":1,"cha":1},"combat":{"melee":3,"ranged":null,"dodge":15,"disengage":15,"casting":1},"attacks":[{"name":"Multiattack","text":"Multiattack: Tentacles ×4, reach 60 ft, 2d20 each, +3d2 madness.","multiattack":true,"recharge":null,"limit":null,"damage":["2d20"],"status":[{"dice":"3d2","n":3,"status":"madness"}]},{"name":"Dream Leak","text":"*Dream Leak* (2-turn recharge): everyone within a mile makes a WIS save or takes +3d2 madness.","multiattack":false,"recharge":2,"limit":null,"damage":[],"status":[{"dice":"3d2","n":3,"status":"madness"}]}],"traits":[{"name":"Aberration","text":"*Aberration*."},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–9 of the mind school."},{"name":"Tempo","text":"*Tempo*: it acts three times a round."},{"name":"Asleep","text":"*Asleep*: while it sleeps, its only action is Dream Leak, once a night, out to 50 miles."},{"name":"Undying","text":"*Undying*: it can be put back to sleep, but never killed."}],"harvest":"None.","role":"Set piece","wants":"To keep dreaming.","tactics":"It stays asleep unless it's harmed. The adventure is about stopping whoever is trying to wake it, or putting it back under.","tell":"the dreams get louder every night.","exploit":"lullaby rituals.","type":"Aberration","kind":"creature","order":156},{"id":"screamroot","name":"Screamroot","kr":1,"section":"Plants","typeLine":"Plant","tags":[],"description":"A root shaped like a little person that shrieks when it's pulled from the ground.","hp":6,"hpNote":null,"defence":0,"minHit":0,"speed":"10 ft","stats":{"str":18,"dex":14,"con":14,"int":20,"wis":14,"cha":20},"combat":{"melee":null,"ranged":null,"dodge":14,"disengage":null,"casting":null},"attacks":[{"name":"Scream","text":"*Scream* (once): everyone within 30 ft makes a WIS save or takes 2d6 and is stunned for 1 turn.","multiattack":false,"recharge":null,"limit":"once","damage":["2d6"],"status":[]}],"traits":[{"name":"Plant","text":"*Plant*."}],"harvest":"The root (a powerful alchemy ingredient).","role":"Hazard","wants":"To stay in the ground.","tactics":"Screams once when it's pulled up.","tell":"leaves shaped like little hands.","exploit":"wax in your ears.","type":"Plant","kind":"creature","order":157},{"id":"strangle-vine","name":"Strangle Vine","kr":2,"section":"Plants","typeLine":"Plant","tags":[],"description":"A creeper in old ruins that looks like every other vine until it moves.","hp":18,"hpNote":null,"defence":0,"minHit":0,"speed":"5 ft","stats":{"str":8,"dex":18,"con":8,"int":20,"wis":14,"cha":20},"combat":{"melee":9,"ranged":null,"dodge":16,"disengage":null,"casting":null},"attacks":[{"name":"Lash","text":"Lash: reach 15 ft, 1d6, and the target is grabbed.","multiattack":false,"recharge":null,"limit":null,"damage":["1d6"],"status":[]},{"name":"Strangle","text":"*Strangle*: a grabbed target takes 2d6 a turn and can't breathe.","multiattack":false,"recharge":null,"limit":null,"damage":["2d6"],"status":[]}],"traits":[{"name":"Plant","text":"*Plant*."},{"name":"False Appearance","text":"*False Appearance*: while it's still, it looks like an ordinary vine."}],"harvest":"Vine fibre (strong rope).","role":"Lurker","wants":"Something to strangle.","tactics":"Grabs whoever walks under it.","tell":"thick vines hanging over a doorway.","exploit":"fire.","type":"Plant","kind":"creature","order":158},{"id":"spore-walker","name":"Spore Walker","kr":4,"section":"Plants","typeLine":"Plant","tags":[],"description":"A shambling mushroom-person from deep caves. Peaceful in its colony, and deadly when it defends it.","hp":32,"hpNote":null,"defence":1,"minHit":0,"speed":"20 ft","stats":{"str":8,"dex":14,"con":8,"int":14,"wis":9,"cha":15},"combat":{"melee":8,"ranged":null,"dodge":15,"disengage":13,"casting":null},"attacks":[{"name":"Fist","text":"Fist: 1d10.","multiattack":false,"recharge":null,"limit":null,"damage":["1d10"],"status":[]},{"name":"Spore Puff","text":"*Spore Puff* (2-turn recharge): everyone within 10 ft makes a strength save or is poisoned, +1d2 confused.","multiattack":false,"recharge":2,"limit":null,"damage":[],"status":[{"dice":"1d2","n":1,"status":"confused"}]}],"traits":[{"name":"Plant","text":"*Plant*."},{"name":"Rapport Spores","text":"*Rapport Spores*: members of a colony share thoughts within 120 ft."}],"harvest":"Spores (alchemy).","role":"Controller","wants":"Its colony left alone.","tactics":"Puffs spores to confuse intruders, and only punches if pressed.","tell":"its cap pulses.","exploit":"it's peaceful, and its rapport spores let you talk to it.","type":"Plant","kind":"creature","order":159},{"id":"bloodthorn-thicket","name":"Bloodthorn Thicket","kr":6,"section":"Plants","typeLine":"Plant","tags":[],"description":"A hedge of red thorns that drinks blood and slowly closes around anyone inside it.","hp":60,"hpNote":null,"defence":2,"minHit":0,"speed":"5 ft","stats":{"str":6,"dex":18,"con":5,"int":20,"wis":14,"cha":20},"combat":{"melee":8,"ranged":null,"dodge":18,"disengage":null,"casting":null},"attacks":[{"name":"Thorn lash ×3","text":"Thorn lash ×3: reach 10 ft, 1d8 each, +2d2 bleed. One lash per action.","multiattack":false,"recharge":null,"limit":null,"damage":["1d8"],"status":[{"dice":"2d2","n":2,"status":"bleed"}]}],"traits":[{"name":"Plant","text":"*Plant*."},{"name":"Thicket","text":"*Thicket*: it fills a 20 ft area, and moving inside it costs 1d6 bleed per 5 ft."},{"name":"Blood-fed","text":"*Blood-fed*: it heals as much as the bleed damage it causes."}],"harvest":"Bloodthorns (a blood-magic reagent).","role":"Hazard","wants":"Blood.","tactics":"Slowly closes in around anyone inside it.","tell":"the thorns are red at the tips.","exploit":"fire.","type":"Plant","kind":"creature","order":160},{"id":"thorn-shambler","name":"Thorn Shambler","kr":8,"section":"Plants","typeLine":"Plant","tags":[],"description":"A walking mound of rotting vegetation bristling with thorns.","hp":70,"hpNote":null,"defence":2,"minHit":2,"speed":"20 ft, swim 20 ft","stats":{"str":5,"dex":14,"con":5,"int":17,"wis":12,"cha":18},"combat":{"melee":7,"ranged":null,"dodge":16,"disengage":15,"casting":null},"attacks":[{"name":"Multiattack","text":"Multiattack: Slam ×2, 2d8 each, +1d2 bleed. If both hit the same target, it's engulfed: restrained, and taking 2d8 a turn.","multiattack":true,"recharge":null,"limit":null,"damage":["2d8","2d8"],"status":[{"dice":"1d2","n":1,"status":"bleed"}]}],"traits":[{"name":"Plant","text":"*Plant*."},{"name":"Thorn Hide","text":"*Thorn Hide*: melee attackers take 1d6."},{"name":"Water-fed","text":"*Water-fed*: water damage heals it instead."}],"harvest":"Thorn hide.","role":"Brute","wants":"Damp ground to root in.","tactics":"Engulfs one target and holds on.","