10"],"status":[{"dice":"8d2","n":8,"status":"flavour status"}]}],"traits":[{"name":null,"text":"Everything the Elder has, plus:"},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–8."},{"name":"Ancient Tempo","text":"*Ancient Tempo*: it acts three times a round."},{"name":"Unyielding","text":"*Unyielding*: once a day, when it would drop to 0 HP, it stays at 1 HP and its breath recharges."},{"name":"Signature Move","text":"*Signature Move*: its flavour's Ancient upgrade."},{"name":"Domain","text":"*Domain*: 10 miles."}],"harvest":"As Elder, plus a dragon's heart (legendary item core).","role":"Solo","wants":"Its legacy, and nations' tribute.","tactics":"Uses Breath from a distance before the party can close, and its signature move to reshape the fight.","tell":"as Juvenile.","exploit":"ancient pacts, rivals of the same age, and its weakness.","type":"Dragon","kind":"tier","family":"dragon","tier":"Ancient","tierNumber":4,"order":193},{"id":"primordial-dragon","name":"Primordial Dragon","kr":600,"section":"Dragons","typeLine":"Dragon","tags":[],"description":"The first dragon of its flavour, older than most gods. Each one is unique: there is one of each flavour, at most.","hp":6000,"hpNote":null,"defence":8,"minHit":14,"speed":"60 ft, fly 150 ft","stats":{"str":1,"dex":3,"con":1,"int":1,"wis":1,"cha":1},"combat":{"melee":3,"ranged":3,"dodge":10,"disengage":8,"casting":1},"attacks":[{"name":"Multiattack","text":"Multiattack: Bite 3d50, +5d2 flavour status, and Claws ×2, 2d50 each.","multiattack":true,"recharge":null,"limit":null,"damage":["3d50","2d50"],"status":[{"dice":"5d2","n":5,"status":"flavour status"}]},{"name":"Tail","text":"Tail: reach 40 ft, 6d12, +4d2 prone.","multiattack":false,"recharge":null,"limit":null,"damage":["6d12"],"status":[{"dice":"4d2","n":4,"status":"prone"}]},{"name":"Wing Buffet","text":"*Wing Buffet* (as Elder, 60 ft).","multiattack":false,"recharge":null,"limit":"as Elder, 60 ft","damage":[],"status":[]},{"name":"Breath","text":"*Brea